<?php
// ============================================================
// Beheer > Aanmeldingen
// ============================================================
require_once dirname(__DIR__) . '/auth.php';
require_once dirname(__DIR__) . '/app/auth-capabilities.php';
require_once dirname(__DIR__) . '/app/data-slot.php';
require_once dirname(__DIR__) . '/aanmeldingen-opslag.php';
require_once dirname(__DIR__) . '/app/leden/aanmeldingen-service.php';
if(!$ingelogd){header('Location: ./');exit;}
if(!authHeeftCapability('applications.manage')){http_response_code(403);echo'Geen toegang tot Aanmeldingen.';exit;}
function aaEsc($v):string{return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}
function aaFlash(string $tekst,string $type='ok'):void{$_SESSION['aanmeldingen_flash']=['tekst'=>$tekst,'type'=>$type];}
function aaRedirect():void{header('Location: aanmeldingen.php');exit;}
function aaNaam(array $a):string{return trim(implode(' ',array_filter([(string)($a['voornaam']??''),(string)($a['tussenvoegsel']??''),(string)($a['achternaam']??'')])));}
if(($_SERVER['REQUEST_METHOD']??'GET')==='GET'){$opgeruimd=aanmeldingenOpschonenBewaartermijn();if($opgeruimd>0)schrijfLog($logBestand,$huidigeGebruiker,'aanmeldingen_retentie',(string)$opgeruimd.' afgehandelde aanvraag/aanvragen verwijderd');}
$flash=$_SESSION['aanmeldingen_flash']??null;unset($_SESSION['aanmeldingen_flash']);
if(($_SERVER['REQUEST_METHOD']??'')==='POST'){
    if(!csrfOk()){aaFlash('Sessie verlopen. Ververs de pagina.','fout');aaRedirect();}$actie=(string)($_POST['actie']??'');$id=trim((string)($_POST['id']??''));
    if($actie==='accepteren'){
        try{$resultaat=aanmeldingServiceAccepteer($id,trim((string)($_POST['lidmaatschap_type']??'')),$huidigeGebruiker);schrijfLog($logBestand,$huidigeGebruiker,'aanmelding_geaccepteerd',$id.' · '.($resultaat['type']['id']??'').' · '.($resultaat['contributie_jaar']??''));aaFlash('Aanmelding geaccepteerd. Lid en contributieregel zijn aangemaakt.');}
        catch(Throwable $e){error_log('[beheer/aanmeldingen] accepteren: '.$e->getMessage());aaFlash($e->getMessage()?:'Accepteren mislukt.','fout');}aaRedirect();
    }
    $slot=dataSlotOpen();try{$inbox=aanmeldingenLees();$idx=aanmeldingenVindIndex($inbox,$id);if($idx===null)aaFlash('Aanmelding niet gevonden.','fout');else{$a=$inbox['aanmeldingen'][$idx];$status=(string)($a['status']??'nieuw');if($actie==='afwijzen'){if($status!=='nieuw')aaFlash('Alleen een nieuwe aanmelding kan worden afgewezen.','fout');else{$inbox['aanmeldingen'][$idx]['status']='afgewezen';$inbox['aanmeldingen'][$idx]['beoordeeld_op']=date('c');$inbox['aanmeldingen'][$idx]['beoordeeld_door']=$huidigeGebruiker;$inbox['aanmeldingen'][$idx]['opmerking']=trim(substr((string)($_POST['opmerking']??''),0,500));$inbox['aanmeldingen'][$idx]['gewijzigd']=date('c');if(aanmeldingenSchrijf($inbox)){schrijfLog($logBestand,$huidigeGebruiker,'aanmelding_afgewezen',$id);aaFlash('Aanmelding afgewezen.');}else aaFlash('Opslaan mislukt.','fout');}}
        elseif($actie==='verwijderen'){if($status==='nieuw')aaFlash('Beoordeel de aanmelding eerst; een open aanvraag wordt niet verwijderd.','fout');else{array_splice($inbox['aanmeldingen'],$idx,1);if(aanmeldingenSchrijf($inbox)){schrijfLog($logBestand,$huidigeGebruiker,'aanmelding_verwijderd',$id);aaFlash('Afgehandelde aanmelding verwijderd.');}else aaFlash('Verwijderen mislukt.','fout');}}
        else aaFlash('Onbekende actie.','fout');}}finally{dataSlotDicht($slot);}aaRedirect();
}
$data=aanmeldingenLees();$filter=(string)($_GET['status']??'open');$lijst=$data['aanmeldingen'];usort($lijst,static fn($a,$b)=>strcmp((string)($b['aangemaakt']??''),(string)($a['aangemaakt']??'')));if($filter==='open')$lijst=array_values(array_filter($lijst,static fn($a)=>($a['status']??'nieuw')==='nieuw'));elseif(in_array($filter,['geaccepteerd','afgewezen'],true))$lijst=array_values(array_filter($lijst,static fn($a)=>($a['status']??'')===$filter));
?><!doctype html><html lang="nl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title>Aanmeldingen</title><style>body{margin:0;background:#f6f2e8;color:#26351d;font-family:system-ui,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif}.top{padding:14px 22px;background:#fff;border-bottom:1px solid #ddd8c0}.top a{color:#2d6260;font-weight:750;text-decoration:none}.wrap{max-width:1100px;margin:30px auto;padding:0 20px 70px}.filters,.accept{display:flex;gap:8px;flex-wrap:wrap;align-items:end}.filters a,.btn{display:inline-block;padding:9px 12px;border-radius:8px;text-decoration:none;border:1px solid #d5cfba;background:#fff;color:#2d6260;font-weight:700;cursor:pointer}.kaart{background:#fff;border:1px solid #ddd8c0;border-radius:14px;padding:20px;margin:15px 0}.meta{color:#68705f;font-size:13px}.grid{display:grid;grid-template-columns:repeat(3,1fr);gap:10px}.btn.ok{background:#3a7a77;color:#fff;border:0}.btn.gevaar{background:#fff0ed;color:#8b2e27}.flash{padding:12px;border-radius:9px;margin:15px 0;background:#eaf6ee}.flash.fout{background:#fdeceb;color:#8b2e27}textarea,select{box-sizing:border-box;padding:8px;border:1px solid #d5cfba;border-radius:7px}textarea{width:100%;min-height:70px}.accept label{display:grid;gap:4px;font-weight:700}@media(max-width:700px){.grid{grid-template-columns:1fr}}</style></head><body><div class="top"><a href="./">← Beheer</a></div><main class="wrap"><h1>Aanmeldingen</h1><p>Open aanvragen blijven staan tot beoordeling. Afgehandelde aanvragen worden na <?=aaEsc(aanmeldingenBewaardagen())?> dagen automatisch verwijderd.</p><?php if($flash):?><div class="flash <?=aaEsc($flash['type']??'')?>"><?=aaEsc($flash['tekst']??'')?></div><?php endif;?><nav class="filters"><a href="?status=open">Open</a><a href="?status=geaccepteerd">Geaccepteerd</a><a href="?status=afgewezen">Afgewezen</a><a href="?status=alles">Alles</a></nav><?php if(!$lijst):?><p>Geen aanmeldingen in deze selectie.</p><?php endif;?><?php foreach($lijst as $a):$types=aanmeldingServiceToegestaneTypes($a);$stored=(string)($a['lidmaatschap_type']??'');?><section class="kaart"><h2><?=aaEsc(aaNaam($a))?></h2><p class="meta"><?=aaEsc($a['status']??'nieuw')?> · <?=aaEsc($a['aangemaakt']??'')?> · id <?=aaEsc($a['id']??'')?></p><div class="grid"><div><strong>Contact</strong><br><?=aaEsc($a['email']??'')?><br><?=aaEsc($a['telefoon']??'')?></div><div><strong>Adres</strong><br><?=aaEsc(($a['straat']??'').' '.($a['huisnummer']??''))?><br><?=aaEsc(($a['postcode']??'').' '.($a['gemeente']??''))?></div><div><strong>Aanvraag</strong><br>Geboren <?=aaEsc($a['geboortedatum']??'')?><br>Tariefjaar <?=aaEsc(aanmeldingServiceJaar($a))?> · maand <?=aaEsc(aanmeldingServiceMaand($a))?><?php if($stored!==''):?><br>Aangevraagd type: <?=aaEsc($stored)?><?php endif;?></div></div><?php if(($a['status']??'nieuw')==='nieuw'):?><div class="filters" style="margin-top:15px"><form method="post" class="accept"><input type="hidden" name="csrf" value="<?=aaEsc($csrfToken)?>"><input type="hidden" name="actie" value="accepteren"><input type="hidden" name="id" value="<?=aaEsc($a['id']??'')?>"><label>Lidmaatschapstype<select name="lidmaatschap_type" required><option value="">Kies…</option><?php foreach($types as $type):[$bedrag,$inschrijf]=aanmeldingServiceBedragen($a,$type);?><option value="<?=aaEsc($type['id'])?>" <?=$stored===$type['id']?'selected':''?>><?=aaEsc(lidmaatschapLabel($type,'nl'))?> · €<?=aaEsc(number_format($bedrag+$inschrijf,2,',','.'))?> totaal</option><?php endforeach;?></select></label><button class="btn ok" type="submit" <?=!$types?'disabled':''?>>Accepteren → lid</button></form><form method="post"><input type="hidden" name="csrf" value="<?=aaEsc($csrfToken)?>"><input type="hidden" name="actie" value="afwijzen"><input type="hidden" name="id" value="<?=aaEsc($a['id']??'')?>"><textarea name="opmerking" maxlength="500" placeholder="Reden/notitie (optioneel)"></textarea><button class="btn gevaar" type="submit">Afwijzen</button></form></div><?php if(!$types):?><p class="meta">Geen actief lidmaatschapstype past bij de geboortedatum. Pas eerst Lidmaatschapstypen aan.</p><?php endif;?><?php else:?><p class="meta">Beoordeeld door <?=aaEsc($a['beoordeeld_door']??'')?> op <?=aaEsc($a['beoordeeld_op']??'')?><?=($a['lid_id']??'')!==''?' · lid-id '.aaEsc($a['lid_id']):''?></p><form method="post" onsubmit="return confirm('Afgehandelde aanvraag uit de inbox verwijderen?');"><input type="hidden" name="csrf" value="<?=aaEsc($csrfToken)?>"><input type="hidden" name="actie" value="verwijderen"><input type="hidden" name="id" value="<?=aaEsc($a['id']??'')?>"><button class="btn gevaar" type="submit">Inboxrecord verwijderen</button></form><?php endif;?></section><?php endforeach;?></main></body></html>
